from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient

def sign_or_verify_key(payload, key_id, action):
    credential = DefaultAzureCredential()
    with CryptographyClient(key_id, credential=credential) as client:
        if action == 'sign':
            response = client.sign(algorithm='ES256', digest=payload)
            return response.signature
        elif action == 'verify':
            response = client.verify(algorithm='ES256', digest=payload, signature=key_id)
            return response.is_valid
        else:
            raise ValueError('Invalid action. Use either sign or verify.')

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient

def get_cryptography_client(key_id):
    credential = DefaultAzureCredential()
    return CryptographyClient(key_id, credential=credential)

class EncryptionResponse:
    def __init__(self, ciphertext, iv, tag, key_id, algorithm):
        self.ciphertext = ciphertext
        self.iv = iv
        self.tag = tag
        self.key_id = key_id
        self.algorithm = algorithm

class DecryptionResponse:
    def __init__(self, plaintext):
        self.plaintext = plaintext

class SignatureResponse:
    def __init__(self, signature):
        self.signature = signature

class VerificationResponse:
    def __init__(self, is_valid):
        self.is_valid = is_valid

import re

def payload_safety(plaintext):
    unsafe_patterns = [r'<script>', r'<iframe>', r'<object>']
    for pattern in unsafe_patterns:
        if re.search(pattern, plaintext):
            return False
    return True

